#include <stdio.h>
int main(void){
    int n=6;
    int adj[6][6]={0};
    int e[][2]={{0,1},{0,2},{1,3},{2,3},{3,4}};
    int m=5;
    for(int k=0;k<m;k++){ adj[e[k][0]][e[k][1]]=1; adj[e[k][1]][e[k][0]]=1; }
    int dist[6],q[6],head=0,tail=0;
    for(int i=0;i<n;i++) dist[i]=-1;
    dist[0]=0; q[tail++]=0;
    while(head<tail){
        int u=q[head++];
        for(int v=0;v<n;v++) if(adj[u][v] && dist[v]<0){ dist[v]=dist[u]+1; q[tail++]=v; }
    }
    printf("dist from 0: ");
    for(int i=0;i<n;i++) printf("%d ", dist[i]);
    printf("\n");
    return 0;
}
